main () {
unordered map < , > ht ;
ht . insert ( pair < , > (254 ,10));
ht . insert ( pair < , > (54 ,11));
ht . insert ( pair < , > (54 ,22));
( unordered map < , >:: iterator iter = ht . begin ();
iter ht . end (); iter ++)
std :: cout << " ( " << ( iter ). first << " ," << ( iter ). second << " ) "
<< " has count " << ht . count (( iter ). first )
<< std :: endl ;
std :: cout << " Data value for key 54 = " << ( ht . find (54)) - > second
<< std :: endl ;
0;
